"""Metadata-Aware RAG System (dependency-free).

A complete, runnable implementation of a Retrieval-Augmented Generation
system in which document metadata is used for two purposes:

1. FILTERING - candidate documents are narrowed with metadata predicates
   (e.g. category == "billing", priority >= 3) derived from the query.
2. RANKING   - retrieved candidates are re-scored by combining semantic
   similarity with a configurable metadata-relevance score so the most
   pertinent documents surface to the top of the context window.

Design goals
------------
* Standard-library only (no API keys, no network access required).
* Generic metadata rules: all boosts/filters are user configurable.
* Transparent: every retrieval returns the filter applied and the score
  breakdown (semantic vs metadata) for each document.

Modules in this file
--------------------
Document / RetrievalResult      : core data types
HashingEmbedder / cosine        : embeddings & similarity
RecursiveTextSplitter           : chunking
matches_metadata                : metadata predicate matcher
InMemoryVectorStore             : store + filtered similarity search
MetadataRanker / KeywordBoost   : generic metadata ranking rules
QueryFilterBuilder              : query -> metadata filter inference
MetadataAwareRetriever          : filter + rank + combine
RAGPipeline                     : end-to-end answer generation
evaluate                        : precision@k / recall@k / MRR
main()                          : demo over bundled sample documents
"""

from __future__ import annotations

import hashlib
import heapq
import math
import re
from dataclasses import dataclass, field
from typing import Callable, Dict, Iterable, List, Optional, Sequence, Tuple


# ---------------------------------------------------------------------------
# 1. Core data types
# ---------------------------------------------------------------------------

@dataclass
class Document:
    """A retrievable text unit with arbitrary metadata attached."""
    page_content: str
    metadata: Dict[str, object] = field(default_factory=dict)
    id: str = ""

    def __post_init__(self) -> None:
        if not self.id:
            self.id = hashlib.md5(self.page_content.encode("utf-8")).hexdigest()[:12]

    def meta_text(self, fields: Sequence[str]) -> str:
        """Concatenate selected metadata fields into a searchable string."""
        parts = []
        for f in fields:
            v = self.metadata.get(f)
            if isinstance(v, (list, tuple, set)):
                v = " ".join(str(x) for x in v)
            if v is not None:
                parts.append(str(v))
        return " ".join(parts)


@dataclass
class RetrievalResult:
    """One ranked hit: the document plus the scoring breakdown."""
    document: Document
    score: float                       # final combined score
    semantic_score: float = 0.0        # normalized cosine similarity
    metadata_score: float = 0.0        # normalized metadata relevance
    matched_filter: Dict = field(default_factory=dict)


# ---------------------------------------------------------------------------
# 2. Embeddings (hashing vectorizer, deterministic, no dependencies)
# ---------------------------------------------------------------------------

def _features(text: str, word_ngrams: Tuple[int, int] = (1, 2),
              char_ngram: int = 3) -> List[str]:
    """Produce lightweight lexical features: lowercase words, word n-grams,
    and character n-grams (robust to punctuation and typos)."""
    text = text.lower()
    words = re.findall(r"[a-z0-9]+", text)
    feats: List[str] = []
    # word n-grams
    lo, hi = word_ngrams
    for n in range(lo, hi + 1):
        for i in range(len(words) - n + 1):
            feats.append("w:" + " ".join(words[i:i + n]))
    # character n-grams over the whole text (bounded to keep it fast)
    flat = re.sub(r"\s+", " ", text).strip()
    if char_ngram and len(flat) >= char_ngram:
        step = max(1, len(flat) // 2000)
        feats.extend("c:" + flat[i:i + char_ngram]
                     for i in range(0, len(flat) - char_ngram + 1, step))
    return feats


class HashingEmbedder:
    """Map text to a fixed-size normalized vector using feature hashing with
    sublinear term-frequency weighting (a tiny 'hashing trick' TF embedder)."""

    def __init__(self, dim: int = 1024, word_ngrams: Tuple[int, int] = (1, 2),
                 char_ngram: int = 3) -> None:
        self.dim = dim
        self.word_ngrams = word_ngrams
        self.char_ngram = char_ngram

    def _hash(self, feature: str) -> int:
        # blake2b -> 8 bytes -> int in [0, dim)
        digest = hashlib.blake2b(feature.encode("utf-8"), digest_size=8).digest()
        return int.from_bytes(digest, "little") % self.dim

    def embed(self, text: str) -> List[float]:
        counts: Dict[int, float] = {}
        for feat in _features(text, self.word_ngrams, self.char_ngram):
            idx = self._hash(feat)
            counts[idx] = counts.get(idx, 0.0) + 1.0
        vec = [0.0] * self.dim
        for idx, tf in counts.items():
            # sublinear TF: w = 1 + log(tf)
            vec[idx] = 1.0 + math.log(tf)
        norm = math.sqrt(sum(v * v for v in vec)) or 1.0
        return [v / norm for v in vec]


def cosine_similarity(a: Sequence[float], b: Sequence[float]) -> float:
    """Dot product of two normalized vectors (or plain cosine otherwise)."""
    return sum(x * y for x, y in zip(a, b))


# ---------------------------------------------------------------------------
# 3. Text chunking
# ---------------------------------------------------------------------------

class RecursiveTextSplitter:
    """Recursively split on [paragraph, newline, sentence, word] boundaries
    while honouring chunk_size and chunk_overlap."""

    def __init__(self, chunk_size: int = 800, chunk_overlap: int = 120) -> None:
        if chunk_overlap >= chunk_size:
            raise ValueError("chunk_overlap must be smaller than chunk_size")
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap
        self._separators = ["\n\n", "\n", ". ", " "]

    def split_text(self, text: str) -> List[str]:
        return self._split(text, self.chunk_size)

    def _split(self, text: str, size: int) -> List[str]:
        if len(text) <= size:
            return [text] if text.strip() else []
        # try to find the best separator near the size limit
        for sep in self._separators:
            cut = text.rfind(sep, 0, size)
            if cut > size // 2:
                head, tail = text[:cut], text[cut + len(sep):]
                break
        else:  # no good boundary: hard cut
            head, tail = text[:size], text[size:]
        head = head.strip()
        overlap_start = max(0, len(head) - self.chunk_overlap)
        tail = (head[overlap_start:] + " " + tail).strip() if head else tail
        return [head] + self._split(tail, size)

    def split_documents(self, docs: Sequence[Document]) -> List[Document]:
        out: List[Document] = []
        for doc in docs:
            for i, chunk in enumerate(self.split_text(doc.page_content)):
                meta = dict(doc.metadata)
                meta["chunk_index"] = i
                out.append(Document(page_content=chunk, metadata=meta,
                                    id=f"{doc.id}:{i}"))
        return out


# ---------------------------------------------------------------------------
# 4. Metadata predicate matching (filter language)
# ---------------------------------------------------------------------------

def _cmp(value, op: str, expected) -> bool:
    try:
        if op == "$eq":
            return value == expected
        if op == "$ne":
            return value != expected
        if op == "$in":
            return value in expected
        if op == "$nin":
            return value not in expected
        if op in ("$gt", "$gte", "$lt", "$lte"):
            if value is None:
                return False
            if op == "$gt":
                return value > expected
            if op == "$gte":
                return value >= expected
            if op == "$lt":
                return value < expected
            return value <= expected
    except TypeError:
        return False
    return False


def _field_matches(value, constraint) -> bool:
    # {"category": "api"}              -> equality
    # {"category": ["api", "billing"]} -> membership
    # {"priority": {"$gte": 3}}        -> operator form
    if isinstance(constraint, dict) and any(
            k.startswith("$") for k in constraint):
        return all(_cmp(value, op, exp) for op, exp in constraint.items())
    if isinstance(constraint, (list, tuple, set)):
        return value in constraint
    if isinstance(value, (list, tuple, set)):
        return constraint in value
    return value == constraint


def matches_metadata(metadata: Dict[str, object], filt: Optional[Dict]) -> bool:
    """Evaluate a metadata filter against a document's metadata.

    Supported syntax (subset of common vector-store filter languages):
        {"category": "api"}
        {"category": ["api", "billing"]}
        {"priority": {"$gte": 3}}
        {"$and": [...], "$or": [...], "$not": {...}}
    Missing metadata fields simply fail equality/in tests and pass $ne/$nin.
    """
    if not filt:
        return True
    for key, constraint in filt.items():
        if key == "$and":
            if not all(matches_metadata(metadata, sub) for sub in constraint):
                return False
        elif key == "$or":
            if not any(matches_metadata(metadata, sub) for sub in constraint):
                return False
        elif key == "$not":
            if matches_metadata(metadata, constraint):
                return False
        else:
            if not _field_matches(metadata.get(key), constraint):
                return False
    return True


# ---------------------------------------------------------------------------
# 5. In-memory vector store with metadata filtering
# ---------------------------------------------------------------------------

@dataclass
class _Entry:
    doc: Document
    vec: List[float]


class InMemoryVectorStore:
    """Minimal vector store: insert documents (with precomputed vectors) and
    run similarity search restricted by a metadata filter."""

    def __init__(self) -> None:
        self._entries: List[_Entry] = []

    def add(self, docs: Sequence[Document],
            embedder: HashingEmbedder) -> None:
        for doc in docs:
            self._entries.append(_Entry(doc, embedder.embed(doc.page_content)))

    @property
    def size(self) -> int:
        return len(self._entries)

    def similarity_search(self, query_vec: Sequence[float], k: int = 10,
                          fetch_k: Optional[int] = None,
                          filt: Optional[Dict] = None,
                          ) -> List[Tuple[Document, float]]:
        """Return up to `k` documents matching `filt`, scored by cosine
        similarity. `fetch_k` bounds how many matching docs are scored."""
        scored: List[Tuple[float, _Entry]] = []
        for e in self._entries:
            if matches_metadata(e.doc.metadata, filt):
                s = cosine_similarity(query_vec, e.vec)
                scored.append((s, e))
        scored.sort(key=lambda t: t[0], reverse=True)
        if fetch_k is not None:
            scored = scored[:fetch_k]
        return [(e.doc, s) for s, e in scored[:k]]


# ---------------------------------------------------------------------------
# 6. Metadata-based relevance ranking (generic & configurable)
# ---------------------------------------------------------------------------

@dataclass(frozen=True)
class KeywordBoost:
    """Rule: if ANY of `keywords` appear in the query AND in the document's
    ranked text, the document receives `weight` metadata-relevance points.
    `fields` selects which document fields are inspected."""
    keywords: Tuple[str, ...]
    weight: float = 1.0
    fields: Tuple[str, ...] = ("title", "tags", "category", "page_content")
    label: str = ""


class MetadataRanker:
    """Computes a normalized metadata-relevance score for a (query, document)
    pair.

    Two configurable signals are combined:
      * FIELD MATCH  - the query text mentions a known value of a metadata
                       field (e.g. category 'billing' or region 'eu').
      * KEYWORD BOOST - the query and the document share topic keywords
                       (supplied by the user through KeywordBoost rules).

    All rules are injected via the constructor; nothing is hard-coded, so
    different corpora/domains can declare their own relevance policy.
    """

    def __init__(self, field_values: Optional[Dict[str, Sequence[str]]] = None,
                 field_weight: float = 2.0,
                 boosts: Optional[Sequence[KeywordBoost]] = None) -> None:
        self.field_values = {k: [str(v).lower() for v in vals]
                             for k, vals in (field_values or {}).items()}
        self.field_weight = field_weight
        self.boosts = list(boosts or [])
        self._max_score = self.field_weight + sum(b.weight for b in self.boosts)

    # -- query helpers ------------------------------------------------------
    def tokenized_query(self, query: str) -> str:
        return re.sub(r"[^a-z0-9 ]", " ", query.lower())

    def matched_field_value(self, query: str) -> Tuple[Optional[str], str]:
        """Return (field, value) if the query names a known metadata value."""
        q = " " + self.tokenized_query(query) + " "
        for field, values in self.field_values.items():
            for value in values:
                if " " + value + " " in q or any(
                        re.search(r"(^|[\s#/-])" + re.escape(value) + r"($|[\s#/.-])", query.lower())
                        for _ in [0]):
                    return field, value
        return None, ""

    # -- scoring ------------------------------------------------------------
    def score(self, query: str, doc: Document) -> float:
        q = self.tokenized_query(query)
        points = 0.0
        # signal 1: metadata field value explicitly requested by the query
        field, value = self.matched_field_value(query)
        if field:
            actual = doc.metadata.get(field)
            if isinstance(actual, (list, tuple, set)):
                hit = any(str(v).lower() == value for v in actual)
            else:
                hit = str(actual).lower() == value
            if hit:
                points += self.field_weight
        # signal 2: keyword boost rules shared by query and document
        for boost in self.boosts:
            if any(k in q for k in boost.keywords):
                doc_text = (" ".join([doc.page_content] +
                                     [doc.meta_text(boost.fields)])).lower()
                if any(k in doc_text for k in boost.keywords):
                    points += boost.weight
        return points / self._max_score if self._max_score else 0.0

    def explain(self, query: str, doc: Document) -> Dict:
        field, value = self.matched_field_value(query)
        matched = []
        if field:
            actual = doc.metadata.get(field)
            hit = (str(actual).lower() == value if not isinstance(actual, (list, tuple, set))
                   else any(str(v).lower() == value for v in actual))
            if hit:
                matched.append(f"field:{field}={value}")
        q = self.tokenized_query(query)
        for boost in self.boosts:
            if any(k in q for k in boost.keywords):
                doc_text = doc.page_content.lower() + " " + doc.meta_text(boost.fields).lower()
                if any(k in doc_text for k in boost.keywords):
                    matched.append(f"keyword:{boost.label or boost.keywords[0]}")
        return {"points": matched, "score": self.score(query, doc)}


# ---------------------------------------------------------------------------
# 7. Query -> metadata filter inference
# ---------------------------------------------------------------------------

class QueryFilterBuilder:
    """Infer a metadata filter from free-text queries by looking for known
    field values. E.g. "how do I fix a failed payment in billing?" with
    field_values={"category": ["billing", "api", ...]} yields
    {"category": "billing"}.

    Only fields whose values are unambiguous tokens are auto-inferred;
    callers may still pass an explicit filter to `retrieve`, which takes
    precedence.
    """

    def __init__(self, field_values: Optional[Dict[str, Sequence[str]]] = None,
                 field_aliases: Optional[Dict[str, str]] = None) -> None:
        self.field_values = {f: [str(v).lower() for v in vs]
                             for f, vs in (field_values or {}).items()}
        self.field_aliases = dict(field_aliases or {})
        # longest alias/value first for deterministic matching
        self._keys: List[Tuple[str, str]] = []
        for field, vals in self.field_values.items():
            for v in vals:
                self._keys.append((field, v))
        self._keys.sort(key=lambda kv: len(kv[1]), reverse=True)

    def build(self, query: str, explicit: Optional[Dict] = None) -> Dict:
        """Combine explicit filters with query-inferred filters."""
        filt: Dict = dict(explicit or {})
        if explicit is None:
            q = query.lower()
            for field, value in self._keys:
                if value in q:
                    filt.setdefault(field, value)
        return filt


# ---------------------------------------------------------------------------
# 8. Metadata-aware retriever (filter -> search -> rank -> combine)
# ---------------------------------------------------------------------------

class MetadataAwareRetriever:
    """Two-stage retrieval:

      Stage A (FILTER) : build a metadata filter from the query (or use the
                         caller-provided one) and run a metadata-filtered
                         similarity search over the vector store.
      Stage B (RANK)   : re-score the candidates by combining normalized
                         semantic similarity with the MetadataRanker score:
                             final = alpha * semantic + (1 - alpha) * meta

    The mixture weight `alpha` controls how strongly metadata relevance
    influences the final ordering.
    """

    def __init__(self, vectorstore: InMemoryVectorStore,
                 embedder: HashingEmbedder,
                 ranker: Optional[MetadataRanker] = None,
                 filter_builder: Optional[QueryFilterBuilder] = None,
                 alpha: float = 0.7) -> None:
        self.vectorstore = vectorstore
        self.embedder = embedder
        self.ranker = ranker or MetadataRanker()
        self.filter_builder = filter_builder or QueryFilterBuilder()
        self.alpha = alpha

    def retrieve(self, query: str, k: int = 4, fetch_k: int = 24,
                 metadata_filter: Optional[Dict] = None,
                 ) -> Tuple[List[RetrievalResult], Dict]:
        """Return (ranked_results, diagnostics) where diagnostics records the
        metadata filter that was applied."""
        filt = self.filter_builder.build(query, metadata_filter)
        qvec = self.embedder.embed(query)
        candidates = self.vectorstore.similarity_search(
            qvec, k=fetch_k, filt=filt)

        results: List[RetrievalResult] = []
        for doc, sem_score in candidates:
            # semantic score normalized to [0, 1] per candidate set
            meta_score = self.ranker.score(query, doc)
            results.append(RetrievalResult(
                document=doc,
                semantic_score=max(0.0, sem_score),
                metadata_score=meta_score,
                score=(self.alpha * max(0.0, sem_score)
                       + (1.0 - self.alpha) * meta_score),
                matched_filter=dict(filt),
            ))
        results.sort(key=lambda r: r.score, reverse=True)
        top = results[:k]
        # re-normalize semantic scores within the final set for readability
        if top:
            hi = max(r.semantic_score for r in top) or 1.0
            for r in top:
                r.semantic_score = round(r.semantic_score / hi, 4)
                r.metadata_score = round(r.metadata_score, 4)
                r.score = round(r.score, 4)
        return top, {"filter": filt, "candidates_scored": len(candidates)}


# ---------------------------------------------------------------------------
# 9. Grounded generation (pluggable LLM + dependency-free default)
# ---------------------------------------------------------------------------

def build_context(query: str, results: Sequence[RetrievalResult],
                  include_metadata: bool = True) -> str:
    """Assemble a numbered, source-cited context block for the generator."""
    lines = [f"Question: {query}", "", "Relevant documents:"]
    for i, r in enumerate(results, start=1):
        header = f"[{i}] "
        if include_metadata:
            meta = {k: v for k, v in r.document.metadata.items()
                    if k not in ("chunk_index",)}
            header += "metadata=" + str(meta) + " | "
        header += f"relevance={r.score:.3f}"
        lines.append(header)
        lines.append(r.document.page_content)
        lines.append("")
    return "\n".join(lines)


class ExtractiveGenerator:
    """Dependency-free answer generator: picks the most relevant sentence from
    the retrieved context (top-1 document, highest-relevance sentence)."""

    def __init__(self, llm: Optional[Callable[[str], str]] = None) -> None:
        # A user-supplied callable (e.g. an LLM client) takes priority.
        self.llm = llm

    def generate(self, query: str,
                 results: Sequence[RetrievalResult]) -> Tuple[str, List[str]]:
        context = build_context(query, results)
        if self.llm is not None:
            answer = self.llm(context)
            return answer, [r.document.id for r in results]
        if not results:
            return ("No relevant documents were found.", [])
        sentences = re.split(r"(?<=[.!?])\s+", results[0].document.page_content)
        scored: List[Tuple[float, str]] = []
        q = self.embedderless_keywords(query)
        for s in sentences:
            s = s.strip()
            if len(s) < 20:
                continue
            sw = self.embedderless_keywords(s)
            overlap = len(q & sw) / (len(q) or 1)
            scored.append((overlap + len(s) / 1000.0, s))
        if not scored:
            answer = results[0].document.page_content
        else:
            answer = max(scored, key=lambda t: t[0])[1]
        return answer, [r.document.id for r in results]

    @staticmethod
    def embedderless_keywords(text: str):
        return set(re.findall(r"[a-z0-9]+", text.lower()))


class RAGPipeline:
    """End-to-end pipeline: retrieve with metadata filter/ranking, then
    generate a grounded answer with citations."""

    def __init__(self, retriever: MetadataAwareRetriever,
                 generator: Optional[ExtractiveGenerator] = None) -> None:
        self.retriever = retriever
        self.generator = generator or ExtractiveGenerator()

    def answer(self, query: str, k: int = 4,
               metadata_filter: Optional[Dict] = None,
               ) -> Dict:
        results, diagnostics = self.retriever.retrieve(
            query, k=k, metadata_filter=metadata_filter)
        answer, source_ids = self.generator.generate(query, results)
        return {
            "query": query,
            "answer": answer,
            "sources": [r.document.id for r in results],
            "applied_filter": diagnostics["filter"],
            "candidates_scored": diagnostics["candidates_scored"],
            "results": results,
        }


# ---------------------------------------------------------------------------
# 10. Evaluation metrics
# ---------------------------------------------------------------------------

def evaluate(retriever: MetadataAwareRetriever,
             queries: Sequence[Dict], k: int = 4) -> Dict[str, float]:
    """queries: [{"query": str, "expected_ids": [str,...]}]

    Computes precision@k, recall@k, and Mean Reciprocal Rank over expected
    document ids.
    """
    precisions, recalls, rr = [], [], []
    for item in queries:
        results, _ = retriever.retrieve(item["query"], k=k)
        retrieved = [r.document.id for r in results]
        expected = set(item["expected_ids"])
        hits = [rid for rid in retrieved if rid in expected]
        precisions.append(len(hits) / k)
        recalls.append(len(hits) / len(expected) if expected else 0.0)
        for rank, rid in enumerate(retrieved, start=1):
            if rid in expected:
                rr.append(1.0 / rank)
                break
        else:
            rr.append(0.0)
    n = len(queries)
    return {
        "precision@k": round(sum(precisions) / n, 4),
        "recall@k": round(sum(recalls) / n, 4),
        "mrr": round(sum(rr) / n, 4),
        "num_queries": n,
    }


# ---------------------------------------------------------------------------
# 11. Demo: sample corpus, index build, queries, evaluation
# ---------------------------------------------------------------------------

def _sample_documents() -> List[Document]:
    """Small fictional corpus about an internal 'Acme Cloud' platform. The
    metadata (category, product_area, priority, audience, tags) exercises both
    filtering (category/product_area) and ranking (priority, tags, audience)."""
    raw = [
        # category=api
        ("api-1", "api", "platform", "api-keys",
         "Creating and rotating API keys", 1, "developers", ["authentication", "api-keys"],
         "API keys are issued from the developer console. Rotate keys every 90 days and "
         "store them in your secret manager. Keys inherit the scopes of the service "
         "account that created them."),
        ("api-2", "api", "platform", "rate-limits",
         "Rate limits for public endpoints", 2, "developers", ["limits", "api"],
         "Public endpoints allow 1000 requests per minute per API key. When you exceed "
         "the limit the server returns HTTP 429 with a Retry-After header. Raise the "
         "limit by contacting support with a business case."),
        # category=billing
        ("bill-1", "billing", "finance", "invoices",
         "Understanding your monthly invoice", 1, "finance-admins", ["invoice", "costs"],
         "Invoices are generated on the first day of each month and itemize usage per "
         "project. Pay by wire transfer or credit card within 30 days. Late invoices "
         "may pause new deployments."),
        ("bill-2", "billing", "finance", "budgets",
         "Setting budgets and alerts", 2, "finance-admins", ["budget", "alerts"],
         "Create budgets per project to track spend. Alerts fire at 50, 80, and 100 "
         "percent of the budget. Budget alerts are delivered by email and Slack."),
        # category=security
        ("sec-1", "security", "platform", "sso",
         "Single sign-on configuration", 1, "security-team", ["sso", "authentication"],
         "Single sign-on (SSO) supports SAML 2.0 and OpenID Connect. Map your identity "
         "provider groups to platform roles. Enforce multi-factor authentication for "
         "every administrator."),
        ("sec-2", "security", "platform", "audit-logs",
         "Audit logs and compliance", 2, "security-team", ["logs", "compliance"],
         "Audit logs record every administrative action with actor, timestamp, and "
         "source IP. Retain audit logs for at least 12 months to satisfy compliance "
         "requirements. Export them through the security API."),
        # category=deployment
        ("dep-1", "deployment", "infrastructure", "blue-green",
         "Zero-downtime blue-green deployments", 1, "platform-engineers", ["deploy", "release"],
         "Blue-green deployment runs two identical environments. Traffic switches to "
         "the green environment after health checks pass, which keeps downtime at "
