        # category=support / docs
        ("sup-1", "support", "operations", "sla",
         "Support tiers and response times", 3, "all", ["support", "sla"],
         "Standard support responds within one business day. Premium support offers a "
         "30 minute response for severity-one incidents. Escalate by filing a ticket "
         "from the support portal."),
        ("sup-2", "support", "operations", "status",
         "Incident status page", 3, "all", ["incident", "status"],
         "The public status page reports incidents in real time. Subscribe to get "
         "notifications by email or webhook. Historical uptime is reported monthly."),
    ]
    docs = []
    for (doc_id, cat, area, slug, title, priority, audience, tags, body) in raw:
        docs.append(Document(
            page_content=body,
            metadata={
                "doc_id": doc_id,
                "category": cat,
                "product_area": area,
                "slug": slug,
                "title": title,
                "priority": priority,
                "audience": audience,
                "tags": tags,
            },
            id=doc_id,
        ))
    return docs


def build_components(docs: Optional[Sequence[Document]] = None,
                     alpha: float = 0.65):
    """Index sample documents and assemble the retriever/pipeline."""
    docs = list(docs) if docs is not None else _sample_documents()

    # --- indexing ----------------------------------------------------------
    splitter = RecursiveTextSplitter(chunk_size=500, chunk_overlap=60)
    chunks = splitter.split_documents(docs)

    embedder = HashingEmbedder(dim=1024, word_ngrams=(1, 2), char_ngram=3)
    store = InMemoryVectorStore()
    store.add(chunks, embedder)

    # --- metadata ranking configuration (fully generic) ---------------------
    field_values = {
        "category": ["api", "billing", "security", "deployment", "support"],
        "product_area": ["platform", "finance", "infrastructure", "operations"],
        "audience": ["developers", "finance-admins", "security-team",
                     "platform-engineers", "all"],
    }
    boosts = [
        # field values are covered by MetadataRanker; these KeywordBoost rules
        # reward documents whose tags/title/topic overlap the query intent.
        KeywordBoost(("deploy", "release", "rollback", "downtime"), 1.5,
                     ("title", "tags", "category", "page_content"), "release-ops"),
        KeywordBoost(("api key", "api-keys", "rotate", "authentication"), 1.0,
                     ("title", "tags", "category", "page_content"), "authn"),
        KeywordBoost(("invoice", "payment", "budget", "cost"), 1.0,
                     ("title", "tags", "category", "page_content"), "cost"),
        KeywordBoost(("sso", "audit", "compliance", "log"), 1.0,
                     ("title", "tags", "category", "page_content"), "security"),
    ]
    ranker = MetadataRanker(field_values=field_values, field_weight=2.0,
                            boosts=boosts)

    # --- query -> filter inference + two-stage retriever ---------------------
    filter_builder = QueryFilterBuilder(field_values=field_values)
    retriever = MetadataAwareRetriever(store, embedder, ranker,
                                       filter_builder, alpha=alpha)
    pipeline = RAGPipeline(retriever)
    return store, retriever, pipeline, chunks


def _demo() -> None:
    print("=" * 78)
    print("METADATA-AWARE RAG DEMO (dependency-free)")
    print("=" * 78)

    store, retriever, pipeline, chunks = build_components()
    print(f"Indexed {len(chunks)} chunks from {store.size} vector entries.\n")

    queries = [
        # (query, expected doc ids, note)
        ("How do I rotate my API keys in the api category?",
         ["api-1"], "metadata filter on category=api + keyword boost"),
        ("What happens when we exceed the api rate limit?",
         ["api-2"], "category filter"),
        ("Show me audit log retention for the security team",
         ["sec-2"], "category=security filter + audience boost"),
        ("How do I roll back a bad release?",
         ["dep-2", "dep-1"], "release-ops keyword boost"),
        ("Invoice payment terms and budget alerts",
         ["bill-1", "bill-2"], "cost keyword boost, no filter"),
    ]

    for q, expected, note in queries:
        print("-" * 78)
        print(f"Q: {q}")
        print(f"  (expects: {expected} | signal: {note})")
        results, diagnostics = retriever.retrieve(q, k=3)
        print(f"  applied metadata filter : {diagnostics['filter']}")
        for r in results:
            m = r.document.metadata
            expl = retriever.ranker.explain(q, r.document)
            print(f"    doc={m['doc_id']:>6} cat={m['category']:<10} "
                  f"score={r.score:<6} sem={r.semantic_score:<6} "
                  f"meta={r.metadata_score:<6} meta_hits={expl['points']}")
        hit = [r.document.metadata['doc_id'] for r in results]
        print(f"  retrieved ids: {hit} | expected top hit present: "
              f"{expected[0] in hit}")

    # --- end-to-end answer ------------------------------------------------
    print("=" * 78)
    out = pipeline.answer("How do I roll back a bad release?", k=3)
    print("ANSWER:", out["answer"])
    print("SOURCES:", out["sources"], "| filter:", out["applied_filter"])

    # --- evaluation ---------------------------------------------------------
    eval_queries = [
        {"query": q, "expected_ids": e} for q, e, _ in queries
    ]
    print("=" * 78)
    print("EVALUATION:", evaluate(retriever, eval_queries, k=3))


if __name__ == "__main__":
    _demo()

