def _list_field_matches(values: list, ops: Dict) -> bool:
    """Operator semantics for list-valued metadata (e.g. tags: ["sso","api"]).

    * $eq/$in/$gt/$gte/$lt/$lte are satisfied when ANY element matches.
    * $ne is satisfied when NO element equals the value.
    * $nin is satisfied when NO element is contained in the list.
    """
    for op, exp in ops.items():
        if op == "$ne":
            if any(v == exp for v in values):
                return False
        elif op == "$nin":
            if any(v in exp for v in values):
                return False
        else:  # $eq, $in, $gt, $gte, $lt, $lte
            if not any(_cmp(v, op, exp) for v in values):
                return False
    return True

